package pe.nexo.store.order;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.List;
public record AdminOrderResponse(Long id,String orderNumber,String customerName,String email,String phone,String address,String status,BigDecimal total,LocalDateTime createdAt,List<Item>items){public record Item(Long productId,String productName,Integer quantity,BigDecimal unitPrice){}public static AdminOrderResponse from(CustomerOrder o){return new AdminOrderResponse(o.getId(),o.getOrderNumber(),o.getCustomerName(),o.getEmail(),o.getPhone(),o.getAddress(),o.getStatus().name(),o.getTotal(),o.getCreatedAt(),o.getItems().stream().map(i->new Item(i.getProductId(),i.getProductName(),i.getQuantity(),i.getUnitPrice())).toList());}}
